AND d.tenant_id = #{tenantId}
AND d.deleted = b'0'

    AND (
        d.device_no LIKE CONCAT('%', #{keyword}, '%')
        OR d.legacy_device_no LIKE CONCAT('%', #{keyword}, '%')
        OR d.serial_number LIKE CONCAT('%', #{keyword}, '%')
        OR d.equipment_model_code LIKE CONCAT('%', #{keyword}, '%')
    )


    AND d.equipment_model_code = #{equipmentModelCode}


    AND d.status = #{deviceStatus}


    AND EXISTS (
        SELECT 1
        FROM rental_delivery_device_rel dr
        INNER JOIN rental_delivery dl ON dl.id = dr.delivery_id
            AND dl.tenant_id = #{tenantId}
            AND dl.deleted = b'0'
            AND dl.lifecycle_status = 'ACTIVE'
        WHERE dr.tenant_id = #{tenantId}
          AND dr.deleted = b'0'
          AND dr.device_id = d.id


                AND dr.device_id = d.id
                AND d.status = 'RENTED'
                AND dl.direction = 'RETURN'
                AND dl.tracking_status = 'RETURNED'


                AND dl.tracking_status = #{logisticsStatus}


    )

mapper.select:
SELECT
    COUNT(1) AS total_devices,
    COALESCE(SUM(
        CASE WHEN d.enabled = b'1'
            AND d.status = 'AVAILABLE'
            AND NOT EXISTS (
                SELECT 1
                FROM rental_schedule s0
                WHERE s0.tenant_id = #{tenantId}
                  AND s0.deleted = b'0'
                  AND s0.device_id = d.id
                  AND s0.status = 'EFFECTIVE'
                  AND s0.occupy_start_date < #{toDateExclusive}
                  AND s0.occupy_end_date_exclusive > #{fromDate}
            )
        THEN 1 ELSE 0 END
    ), 0) AS available_devices,
    COALESCE(SUM(
        CASE WHEN d.status IN ('RENTED', 'MAINTENANCE')
            OR EXISTS (
                SELECT 1
                FROM rental_schedule s1
                WHERE s1.tenant_id = #{tenantId}
                  AND s1.deleted = b'0'
                  AND s1.device_id = d.id
                  AND s1.status = 'EFFECTIVE'
                  AND s1.occupy_start_date < #{toDateExclusive}
                  AND s1.occupy_end_date_exclusive > #{fromDate}
            )
        THEN 1 ELSE 0 END
    ), 0) AS occupied_devices,
    COALESCE(SUM(
        CASE WHEN EXISTS (
            SELECT 1
            FROM rental_delivery_device_rel dr2
            INNER JOIN rental_delivery dl2 ON dl2.id = dr2.delivery_id
                AND dl2.tenant_id = #{tenantId}
                AND dl2.deleted = b'0'
                AND dl2.lifecycle_status = 'ACTIVE'
            WHERE dr2.tenant_id = #{tenantId}
              AND dr2.deleted = b'0'
              AND dr2.device_id = d.id
              AND dl2.tracking_status IN
                  ('PICKED_UP', 'IN_TRANSIT', 'OUT_FOR_DELIVERY', 'RETURNING')
        ) THEN 1 ELSE 0 END
    ), 0) AS in_transit_devices,
    COALESCE(SUM((
        SELECT COALESCE(SUM(DATEDIFF(
            LEAST(s2.occupy_end_date_exclusive, #{toDateExclusive}),
            GREATEST(s2.occupy_start_date, #{fromDate})
        )), 0)
        FROM rental_schedule s2
        WHERE s2.tenant_id = #{tenantId}
          AND s2.deleted = b'0'
          AND s2.device_id = d.id
          AND s2.status = 'EFFECTIVE'
          AND s2.occupy_start_date < #{toDateExclusive}
          AND s2.occupy_end_date_exclusive > #{fromDate}
    )), 0) AS occupied_device_days
FROM rental_device d
WHERE 1 = 1
